function users(){const own=(window.AKTIF_KULLANICI||AppStore?.get?.('session.user'))?.uid||'',edit=canUsers('edit'),list=arr('kullanicilar').slice().sort((a,b)=>{const ap=a.aktif===false?0:1,bp=b.aktif===false?0:1;return ap-bp||userName(a).localeCompare(userName(b),'tr')});return `<section class="ka-stack">${list.length?list.map(u=>{const photo=userPhoto(u),isOwn=u.id===own,t=userTeacher(u);return `<article class="ka-card ka-list-card"><div class="ka-card__body ka-stack"><div class="ka-row"><span class="ka-avatar">${photo?`<img src="${esc(photo)}" alt="">`:esc(userInitials(u))}</span><div class="ka-grow"><strong>${esc(userName(u))}</strong><div class="ka-muted">${esc(u.kullaniciAdi?'@'+u.kullaniciAdi:(u.email||''))}</div></div><span class="ka-badge">${u.aktif===false?'Onay Bekliyor / Pasif':'Aktif'}</span></div><div class="ka-row ka-row--between"><span class="ka-muted">${esc(userRole(u))}${t?` · ${esc(`${t.ad||''} ${t.soyad||''}`.trim())}`:''}</span>${edit?`<div class="ka-row"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-user-edit="${esc(u.id)}">Düzenle</button>${!isOwn?`<button class="ka-btn ka-btn--danger ka-btn--sm" type="button" data-user-delete="${esc(u.id)}">Sil</button>`:''}</div>`:''}</div></div></article>`}).join(''):'<div class="ka-empty">Kullanıcı verisi bulunamadı.</div>'}</section>`}
