function openUserEditor(uid){if(!canUsers('edit'))return;const u=arr('kullanicilar').find(x=>x.id===uid);if(!u)return;document.getElementById('userSettingsEditor')?.remove();const ov=document.createElement('div');ov.id='userSettingsEditor';ov.className='ka-modal-backdrop';ov.innerHTML=`<section class="ka-modal"><div class="ka-modal__header"><div><strong>${esc(userName(u))}</strong><div class="ka-muted">Kullanıcı yetkisi ve öğretmen bağlantısı</div></div><button class="ka-icon-button" type="button" data-user-close aria-label="Kapat">×</button></div><div class="ka-modal__body ka-stack"><label class="ka-field"><span class="ka-field__label">Kullanıcı Adı</span><input value="${esc(u.kullaniciAdi||u.email||'')}" disabled></label><label class="ka-field"><span class="ka-field__label">Rol</span><select data-user-role>${roleOptions(u.rolId||'')}</select></label><label class="ka-field"><span class="ka-field__label">Bağlı Öğretmen Kaydı</span><select data-user-teacher>${teacherOptions(u.bagliOgretmenId||'','— Bağlantı yok —')}</select></label><label class="ka-check"><input type="checkbox" data-user-active ${u.aktif!==false?'checked':''}> Hesap aktif</label><label class="ka-check"><input type="checkbox" data-user-admin ${u.admin?'checked':''} ${admin()?'':'disabled'}> Süper Admin ${admin()?'':'(yalnız süper admin değiştirebilir)'}</label></div><div class="ka-modal__footer"><button class="ka-btn ka-btn--secondary" type="button" data-user-close>Vazgeç</button><button class="ka-btn" type="button" data-user-save>Kullanıcıyı Kaydet</button></div></section>`;document.body.appendChild(ov);ov.querySelectorAll('[data-user-close]').forEach(b=>b.onclick=()=>ov.remove());ov.querySelector('[data-user-save]').onclick=()=>saveUser(uid,ov);window.PermissionService?.apply?.(ov)}
async function saveUser(uid,ov){const own=(window.AKTIF_KULLANICI||AppStore?.get?.('session.user'))?.uid||'',veri={rolId:ov.querySelector('[data-user-role]')?.value||null,bagliOgretmenId:ov.querySelector('[data-user-teacher]')?.value||null,aktif:!!ov.querySelector('[data-user-active]')?.checked};if(admin())veri.admin=!!ov.querySelector('[data-user-admin]')?.checked;const btn=ov.querySelector('[data-user-save]');if(btn){btn.disabled=true;btn.textContent='Kaydediliyor…'}try{await window.KullaniciYonetimiService.kullaniciKaydet(uid,veri,own);toast?.('Kullanıcı cihaz verisinde güncellendi.');ov.remove();render()}catch(e){const msg=e?.message==='kendini-pasif-yapamaz'?'Kendi hesabınızı pasif yapamazsınız.':e?.message==='admin-yetkisi'?'Süper Admin yetkisini yalnız süper admin değiştirebilir.':'Kullanıcı güncellenemedi: '+(e?.message||e);toast?.(msg);if(btn){btn.disabled=false;btn.textContent='Kullanıcıyı Kaydet'}}}
async function deleteUser(uid){if(!canUsers('edit'))return;const own=(window.AKTIF_KULLANICI||AppStore?.get?.('session.user'))?.uid||'',u=arr('kullanicilar').find(x=>x.id===uid);if(!u)return;if(uid===own){toast?.('Kendi hesabınızı silemezsiniz.');return}if(!confirm(`“${userName(u)}” kullanıcısının uygulama profilini ve yetkilerini silmek istiyor musunuz?`))return;try{await window.KullaniciYonetimiService.kullaniciSil(uid,own);toast?.('Kullanıcı cihaz verisinden silindi.');render()}catch(e){const msg=e?.message==='admin-yetkisi'?'Süper Admin hesabını yalnız süper admin silebilir.':e?.message==='kendini-silemez'?'Kendi hesabınızı silemezsiniz.':'Kullanıcı silinemedi: '+(e?.message||e);toast?.(msg)}}
function bindUsers(out){out.querySelectorAll('[data-user-edit]').forEach(b=>b.onclick=()=>openUserEditor(b.dataset.userEdit));out.querySelectorAll('[data-user-delete]').forEach(b=>b.onclick=()=>deleteUser(b.dataset.userDelete))}
function duration(sec){sec=Math.max(0,Number(sec)||0);const h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60);return h?`${h} sa ${m} dk`:m?`${m} dk`:`${Math.round(sec)} sn`}function statDate(v){if(!v)return'—';const d=v?.toDate?v.toDate():new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleString('tr-TR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}function topPage(v){const e=Object.entries(v||{}).sort((a,b)=>Number(b[1]||0)-Number(a[1]||0));return e.length?`${e[0][0]} (${e[0][1]})`:'—'}function mb(v){return`${(Math.max(0,Number(v)||0)/(1024*1024)).toFixed(1)} MB`}function totalStorage(s){const d=s?.depolamaKullanimi||{};return['mesaj','duyuru','dokuman','takvim'].reduce((n,k)=>n+Math.max(0,Number(d[k])||0),0)}
function statUid(x){return String(x?.uid||x?.id||'')}
function statisticsRows(){
  const own=statUid(window.AKTIF_KULLANICI||window.AppStore?.get?.('session.user')),rawStats=arr('kullaniciIstatistikleri'),statsByUid=new Map(rawStats.map(x=>[statUid(x),x]).filter(x=>x[0])),allUsers=arr('kullanicilar'),users=admin()?allUsers:allUsers.filter(u=>statUid(u)===own),seen=new Set(),rows=[];
  for(const u of users){const uid=statUid(u);if(!uid)continue;const stat=statsByUid.get(uid)||null;seen.add(uid);rows.push({...((stat)||{}),id:uid,uid,__user:u,__hasStats:!!stat})}
  if(admin()){for(const stat of rawStats){const uid=statUid(stat);if(!uid||seen.has(uid))continue;rows.push({...stat,id:uid,uid,__user:null,__hasStats:true,__orphan:true})}}
  else if(!rows.length&&own&&statsByUid.has(own)){const stat=statsByUid.get(own);rows.push({...stat,id:own,uid:own,__user:null,__hasStats:true})}
  return rows.sort((a,b)=>Number(b.girisSayisi||0)-Number(a.girisSayisi||0)||String(userName(a.__user||a)||'').localeCompare(String(userName(b.__user||b)||''),'tr',{sensitivity:'base'}))
}
async function prepareStatisticsData(force=false){
  if(statisticsRefreshing)return;statisticsRefreshing=true;if(mounted&&active==='statistics')render();
  try{
    if(window.SyncEngine&&window.COL?.kullanicilar){window.SyncEngine.register('kullanicilar',COL.kullanicilar);await window.SyncEngine.localHydrate(['kullanicilar']);if(navigator.onLine)await window.SyncEngine.pull(['kullanicilar'])}
    if(window.IstatistikService?.prepare){await window.IstatistikService.prepare(admin());if(admin())await window.IstatistikService.prepare(true)}
    if(force&&navigator.onLine&&window.SyncEngine)await window.SyncEngine.pull(['kullaniciIstatistikleri'])
  }catch(e){console.warn('[Kullanıcı İstatistikleri]',e?.message||e)}finally{statisticsRefreshing=false;if(mounted&&active==='statistics')render()}
}
function statisticsIdentity(row){const u=row.__user||{},photo=userPhoto(u),name=row.ad||userName(u)||u.email||'Bilinmeyen kullanıcı',handle=u.kullaniciAdi?`@${u.kullaniciAdi}`:(u.email||''),role=u.id||u.uid?userRole(u):(row.__orphan?'Silinmiş hesap':'Kullanıcı'),initials=userInitials(u)||String(name).trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toLocaleUpperCase('tr')||'K';return{u,photo,name,handle,role,initials}}
function statistics(){
  const rows=statisticsRows(),accounts=rows.filter(x=>x.__user).length,activeUsers=rows.filter(x=>x.__user&&x.__user.aktif!==false).length,tracked=rows.filter(x=>x.__hasStats).length,totals={login:rows.reduce((n,x)=>n+Number(x.girisSayisi||0),0),time:rows.reduce((n,x)=>n+Number(x.toplamSureSaniye||0),0),files:rows.reduce((n,x)=>n+Number(x.dosyaYuklemeSayisi||0),0)},summary=[['👥','Hesaplar',accounts],['↪','Toplam Giriş',totals.login],['◷','Kullanım',duration(totals.time)],['⇧','Dosya',totals.files]];
  return `<section class="ka-statistics-page"><header class="ka-statistics-hero"><div class="ka-statistics-hero__mark" aria-hidden="true">▥</div><div class="ka-statistics-hero__copy"><span>${admin()?'YÖNETİCİ GÖRÜNÜMÜ':'KİŞİSEL ANALİTİK'}</span><h3>Kullanıcı Analitiği</h3><p>${admin()?`${accounts} hesap · ${activeUsers} aktif · ${tracked} istatistik kaydı`:'Kendi kullanım hareketlerinizi görüntülüyorsunuz.'}</p></div><button type="button" class="ka-statistics-refresh" data-stat-refresh ${statisticsRefreshing?'disabled':''} aria-label="İstatistikleri yenile">${statisticsRefreshing?'…':'↻'}</button></header><div class="ka-statistics-summary">${summary.map(([icon,label,value])=>`<article><span aria-hidden="true">${icon}</span><div><small>${label}</small><strong>${esc(value)}</strong></div></article>`).join('')}</div><div class="ka-statistics-list-head"><div><strong>${admin()?'Tüm Kullanıcılar':'Kullanım Özeti'}</strong><small>${admin()?'İstatistik kaydı olmayan hesaplar da listelenir.':'Hesabınıza ait güncel kullanım verileri.'}</small></div><b>${accounts} hesap</b></div><div class="ka-statistics-users">${rows.length?rows.map((s,i)=>{const d=s.depolamaKullanimi||{},id=statUid(s),{u,photo,name,handle,role,initials}=statisticsIdentity(s),muaf=!!u.depolamaMuaf,last=s.sonGiris?statDate(s.sonGiris):'Henüz giriş yapmadı',status=u.id||u.uid?(u.aktif===false?'Pasif':'Aktif'):(s.__orphan?'Hesap silinmiş':'Kayıt yok');return `<article class="ka-statistics-user ${s.__hasStats?'':'is-untracked'}"><header class="ka-statistics-user__head"><span class="ka-statistics-user__avatar">${photo?`<img src="${esc(photo)}" alt="">`:esc(initials)}</span><div class="ka-statistics-user__identity"><div class="ka-statistics-user__name"><strong>${esc(name)}</strong>${u.admin?'<b class="ka-statistics-badge is-admin">Admin</b>':''}</div><small>${esc([handle,role].filter(Boolean).join(' · '))}</small><span class="ka-statistics-last ${s.sonGiris?'':'is-empty'}">${s.sonGiris?'Son giriş: ':''}${esc(last)}</span></div><span class="ka-statistics-rank">${s.__hasStats?`#${i+1}`:'Yeni'}</span></header><div class="ka-statistics-metrics"><div><small>Giriş</small><strong>${Number(s.girisSayisi||0)}</strong></div><div><small>Kullanım</small><strong>${esc(duration(s.toplamSureSaniye))}</strong></div><div><small>Dosya</small><strong>${Number(s.dosyaYuklemeSayisi||0)}</strong></div><div><small>Not</small><strong>${Number(s.notEklemeSayisi||0)}</strong></div></div><div class="ka-statistics-user__meta"><span><b>En çok kullanılan</b>${esc(topPage(s.sayfaZiyaretleri))}</span><span class="ka-statistics-badge ${status==='Aktif'?'is-active':status==='Pasif'?'is-passive':'is-neutral'}">${esc(status)}</span></div><details class="ka-statistics-storage"><summary><span><b>Depolama</b><small>Mesaj, duyuru, doküman ve takvim</small></span><strong>${esc(mb(totalStorage(s)))}</strong><i aria-hidden="true">›</i></summary><div class="ka-statistics-storage__body">${[['Mesaj','mesaj'],['Duyuru','duyuru'],['Doküman','dokuman'],['Takvim','takvim']].map(([label,key])=>`<div><span>${label}</span><strong>${esc(mb(d[key]))}</strong></div>`).join('')}${u.id||u.uid?`<label class="ka-statistics-exempt"><input type="checkbox" data-stat-exempt="${esc(id)}" ${muaf?'checked':''} ${canUsers('edit')?'':'disabled'}><span><b>Depolama sınırından muaf</b><small>Bu kullanıcı için yükleme kotasını uygulama.</small></span></label>`:''}</div></details></article>`}).join(''):'<div class="ka-statistics-empty"><span>👥</span><strong>Kullanıcı hesabı bulunamadı</strong><small>Kullanıcı kayıtları senkronlandığında burada görünecek.</small></div>'}</div></section>`
}
function bindStatistics(out){out.querySelector('[data-stat-refresh]')?.addEventListener('click',()=>prepareStatisticsData(true));out.querySelectorAll('[data-stat-exempt]:not([disabled])').forEach(ch=>ch.onchange=async()=>{const val=ch.checked;ch.disabled=true;try{await window.KullaniciIstatistikleriService.kullaniciMuafiyetKaydet(ch.dataset.statExempt,val);toast?.(val?'Kullanıcı depolama sınırından muaf tutuldu.':'Depolama muafiyeti kaldırıldı.')}catch(e){ch.checked=!val;toast?.('Muafiyet güncellenemedi: '+(e?.message||e))}finally{ch.disabled=false}})}
function explicitPermissionCount(role){const y=role?.yetkiler;return y&&typeof y==='object'?Object.keys(y).length:0}
function assignedRoleCount(id){return arr('kullanicilar').filter(u=>u.rolId===id).length}
function secureRoleDefaults(){const y={};(window.PermissionService?.catalog||[]).filter(x=>x.type==='page'&&String(x.key||'').startsWith('module.')).forEach(x=>{y[x.key]=x.key==='module.dashboard'?'read':'hidden'});return y}
function roles(){const list=arr('roller').slice().sort((a,b)=>String(a.ad||a.rolAdi||'').localeCompare(String(b.ad||b.rolAdi||''),'tr'));return `<section class="ka-stack"><div class="ka-row ka-row--between"><div><strong>Roller</strong><div class="ka-muted">Yeni roller minimum erişimle başlar.</div></div>${canRoles('edit')?'<button class="ka-btn" type="button" data-role-new>+ Yeni Rol</button>':''}</div>${list.length?list.map(r=>`<article class="ka-card ka-list-card"><div class="ka-card__body ka-row"><div class="ka-grow"><strong>${esc(r.ad||r.rolAdi||'Rol')}</strong><div class="ka-muted">${esc(r.aciklama||'')} · ${assignedRoleCount(r.id)} kullanıcı · ${explicitPermissionCount(r)} kural</div></div>${canRoles('edit')?`<button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-role-permissions="${esc(r.id)}">Düzenle</button>`:''}</div></article>`).join(''):'<div class="ka-empty">Rol verisi bulunamadı.</div>'}</section>`}
function rawPermission(role,key){const y=role?.yetkiler||{};return Object.prototype.hasOwnProperty.call(y,key)?window.PermissionService?.normalize?.(y[key])||'':''}
function permissionOptions(selected){return [['','Varsayılan / Üst kural'],['hidden','Gizli'],['preview','Önizleme'],['read','Salt okunur'],['edit','Düzenleme']].map(([v,l])=>`<option value="${v}" ${selected===v?'selected':''}>${l}</option>`).join('')}
function catalogGroups(){const groups=new Map();(window.PermissionService?.catalog||[]).forEach(item=>{const prefix=String(item.key||'').split('.')[0]||'other';if(!groups.has(prefix))groups.set(prefix,[]);groups.get(prefix).push(item)});return groups}
function openRoleEditor(roleId){if(!canRoles('edit'))return;const isNew=roleId==='__new__',found=isNew?null:arr('roller').find(r=>r.id===roleId);if(!isNew&&!found)return;const role=found||{id:null,ad:'',aciklama:'',yetkiler:secureRoleDefaults()};document.getElementById('rolePermissionEditor')?.remove();const body=[...catalogGroups().entries()].map(([group,items])=>`<section class="ka-card"><div class="ka-card__body ka-stack"><div class="ka-row ka-row--between"><strong>${esc(group.toLocaleUpperCase('tr'))}</strong><span class="ka-badge">${items.length} yetki</span></div>${items.map(item=>`<label class="ka-field"><span class="ka-field__label">${esc(item.label)} <span class="ka-muted">· ${esc(item.type)}</span></span><select data-permission-key="${esc(item.key)}">${permissionOptions(rawPermission(role,item.key))}</select><small class="ka-muted">${esc(item.key)}</small></label>`).join('')}</div></section>`).join('');const ov=document.createElement('div');ov.id='rolePermissionEditor';ov.className='ka-modal-backdrop';ov.innerHTML=`<section class="ka-modal"><div class="ka-modal__header"><div><strong>${isNew?'Yeni Rol':esc(role.ad||role.rolAdi||'Rol')}</strong><div class="ka-muted">Rol adı ve merkezi yetki seviyeleri</div></div><button class="ka-icon-button" type="button" data-role-close aria-label="Kapat">×</button></div><div class="ka-modal__body ka-stack"><article class="ka-card"><div class="ka-card__body ka-stack"><label class="ka-field"><span class="ka-field__label">Rol Adı</span><input data-role-name value="${esc(role.ad||role.rolAdi||'')}" placeholder="Örn. Öğretmen"></label><label class="ka-field"><span class="ka-field__label">Açıklama</span><input data-role-description value="${esc(role.aciklama||'')}" placeholder="Bu rolün kullanım amacı"></label><div class="ka-muted">Yeni rol: Ana Sayfa salt okunur, diğer modüller gizli başlar.</div></div></article><article class="ka-card"><div class="ka-card__body"><strong>Yetki seviyeleri</strong><div class="ka-muted">Gizli · Önizleme · Salt okunur · Düzenleme. Modül seviyesi alt işlemler için üst sınırdır.</div></div></article>${body}</div><div class="ka-modal__footer">${!isNew?'<button class="ka-btn ka-btn--danger" type="button" data-role-delete>Rolü Sil</button>':''}<button class="ka-btn ka-btn--secondary" type="button" data-role-close>Vazgeç</button><button class="ka-btn" type="button" data-role-save>Rolü Kaydet</button></div></section>`;document.body.appendChild(ov);ov.querySelectorAll('[data-role-close]').forEach(b=>b.onclick=()=>ov.remove());ov.querySelector('[data-role-save]').onclick=()=>saveRole(role,ov);ov.querySelector('[data-role-delete]')?.addEventListener('click',()=>deleteRole(role,ov));window.PermissionService?.apply?.(ov)}
async function saveRole(role,ov){try{window.PermissionService?.require?.('settings.roles.edit','edit')}catch(_){toast?.('Rol düzenleme yetkiniz yok.');return}const ad=ov.querySelector('[data-role-name]')?.value.trim()||'',aciklama=ov.querySelector('[data-role-description]')?.value.trim()||'';if(!ad){toast?.('Rol adı zorunludur.');return}const next=role.id?{...(role.yetkiler||{})}:secureRoleDefaults();ov.querySelectorAll('[data-permission-key]').forEach(sel=>{const key=sel.dataset.permissionKey;delete next[key];if(sel.value)next[key]=sel.value});const btn=ov.querySelector('[data-role-save]');if(btn){btn.disabled=true;btn.textContent='Kaydediliyor…'}try{const saved=await window.KullaniciYonetimiService.rolKaydet(role.id||null,{ad,aciklama,yetkiler:next});if(role.id&&(window.AKTIF_ROL||AppStore?.get?.('session.role'))?.id===role.id){const updated={...role,ad,aciklama,yetkiler:next};window.AKTIF_ROL=updated;AppStore?.set?.('session.role',updated);window.PermissionService?.refresh?.()}toast?.(role.id?'Rol güncellendi.':'Yeni rol cihaz verisine eklendi.');ov.remove();render();return saved}catch(e){toast?.('Rol kaydedilemedi: '+(e?.message||e));if(btn){btn.disabled=false;btn.textContent='Rolü Kaydet'}}}
async function deleteRole(role,ov){const count=assignedRoleCount(role.id);if(count){toast?.(`Bu role atanmış ${count} kullanıcı var. Önce kullanıcıların rolünü değiştirin.`);return}if(!confirm(`“${role.ad||role.rolAdi||'Rol'}” rolünü silmek istiyor musunuz?`))return;try{await window.KullaniciYonetimiService.rolSil(role.id,count);toast?.('Rol silindi.');ov.remove();render()}catch(e){toast?.(String(e?.message||'').startsWith('rol-kullanimda:')?'Rol kullanımda olduğu için silinemedi.':'Rol silinemedi: '+(e?.message||e))}}
function storage(){const doc=arr('depolamaAyarlari').find(x=>x.id==='ayarlar')||arr('depolamaAyarlari')[0];if(!doc)return'<div class="ka-empty">Depolama ayarları bulunamadı.</div>';return `<article class="ka-card"><div class="ka-card__body ka-stack">${['mesaj','duyuru','dokuman','takvim'].map(k=>{const a=doc[k]||{};return `<div class="ka-row ka-row--between"><span>${esc(k)}</span><strong>${a.aktif===false?'Kapalı':esc((a.MB??100)+' MB')}</strong></div>`}).join('')}</div></article>`}
function reminderSettings(){const doc=arr('hatirlatmaAyarlari').find(x=>x.id==='ayarlar')||arr('hatirlatmaAyarlari')[0]||{};return{gunSayisi:Number(doc.gunSayisi)||3,erteleSaat:Number(doc.erteleSaat)||4}}
function reminders(){const s=reminderSettings();return `<article class="ka-card"><div class="ka-card__body ka-stack"><div><strong>Hatırlatma Davranışı</strong><div class="ka-muted">Dashboard açıldığında görev, evrak, nöbet, çizelge, kontrol listesi ve sınavlar cihaz verisinden taranır.</div></div><div class="ka-grid"><label class="ka-field"><span class="ka-field__label">Kaç gün kala hatırlatma başlasın?</span><input id="reminderDays" type="number" min="1" max="90" step="1" value="${s.gunSayisi}"></label><label class="ka-field"><span class="ka-field__label">Ertele kaç saat gizlesin?</span><input id="reminderSnoozeHours" type="number" min="1" max="168" step="1" value="${s.erteleSaat}"></label></div><div class="ka-row"><span class="ka-badge">Cihaz-first</span><span class="ka-badge">Firestore arka plan senkronu</span></div></div><div class="ka-card__footer"><button class="ka-btn" type="button" data-reminder-settings-save>Hatırlatma Ayarlarını Kaydet</button></div></article>`}
