function menuEditorItem(record,index){const {source:g,item,setting:s}=record,fallback=menuColorValue(menuGroupSetting(g)?.color,MENU_COLOR_DEFAULTS[g.key]||'#17684f'),order=Number(s.order),target=String(s.targetGroup||g.key),label=s.label||item[0],icon=s.icon||item[1]||'';return `<article class="ka-layout-subitem" data-menu-item-row="${esc(menuItemKey(g,item))}" data-menu-item-source="${esc(g.key)}"><div class="ka-layout-subitem__main"><span class="ka-layout-subitem__icon">${esc(icon||'•')}</span><div class="ka-grow"><strong>${esc(label)}</strong><small class="ka-muted">${esc(item[2]||'')}${item[3]?` · ${esc(item[3])}`:''}</small></div><label class="ka-layout-visible"><input type="checkbox" data-menu-item-visible ${s.visible!==false?'checked':''}><span>Göster</span></label></div><div class="ka-layout-subitem__fields"><label class="ka-field"><span class="ka-field__label">Ad</span><input data-menu-item-label value="${esc(label)}"></label><label class="ka-field ka-layout-icon-field"><span class="ka-field__label">İkon</span><input data-menu-item-icon value="${esc(icon)}" maxlength="8"></label><label class="ka-field ka-layout-move-field"><span class="ka-field__label">Başka menüye taşı</span><select data-menu-item-target>${menuTargetOptions(target)}</select></label><label class="ka-field ka-settings-color-field"><span class="ka-field__label">Renk</span><input type="color" data-menu-item-color value="${esc(menuColorValue(s.color,fallback))}"></label><label class="ka-field ka-layout-order-field"><span class="ka-field__label">Sıra</span><input type="number" min="1" step="1" data-menu-item-order value="${Number.isFinite(order)?order:(index+1)*10}"></label></div></article>`}
function menuEditorGroup(g,index){const s=menuGroupSetting(g),records=menuTargetRecords(g.key),order=Number(s.order),color=menuColorValue(s.color,MENU_COLOR_DEFAULTS[g.key]||'#17684f'),selected=g.key===layoutMenu;return `<article class="ka-layout-menu-panel" data-menu-group-row="${esc(g.key)}" data-layout-panel="${esc(g.key)}" ${selected?'':'hidden'}><section class="ka-card ka-layout-menu-config"><div class="ka-card__body"><div class="ka-layout-menu-config__head"><div class="ka-row"><span class="ka-settings-menu-swatch" style="--ka-settings-menu-color:${color}"></span><div><strong>${esc(s.icon||g.icon||'')} ${esc(s.label||g.label)}</strong><small class="ka-muted"><span data-layout-panel-count>${records.length}</span> alt menü</small></div></div><label class="ka-layout-visible"><input type="checkbox" data-menu-group-visible ${s.visible!==false?'checked':''}><span>Menüyü göster</span></label></div><div class="ka-layout-group-fields"><label class="ka-field"><span class="ka-field__label">Menü adı</span><input data-menu-group-label value="${esc(s.label||g.label)}"></label><label class="ka-field ka-layout-icon-field"><span class="ka-field__label">İkon</span><input data-menu-group-icon value="${esc(s.icon||g.icon||'')}" maxlength="8"></label><label class="ka-field ka-settings-color-field"><span class="ka-field__label">Kart rengi</span><input type="color" data-menu-group-color value="${esc(color)}"></label><label class="ka-field ka-layout-order-field"><span class="ka-field__label">Sıra</span><input type="number" min="1" step="1" data-menu-group-order value="${Number.isFinite(order)?order:(index+1)*10}"></label></div></div></section><div class="ka-layout-items-head"><div><h4>Alt menüler</h4><p class="ka-muted">“Başka menüye taşı” alanını değiştirince öğe hedef menüye geçer. Kaydet dediğinizde kalıcı olur.</p></div><span class="ka-badge"><span data-layout-list-count>${records.length}</span> öğe</span></div><div class="ka-layout-item-list" data-layout-item-list>${records.map(menuEditorItem).join('')||'<div class="ka-empty ka-layout-empty">Bu menüde alt öğe yok.</div>'}</div></article>`}
function menuLayoutEditor(){const groups=menuTargetGroups();if(!groups.length)return'<div class="ka-empty">Ana menü kataloğu hazırlanıyor.</div>';if(!groups.some(g=>g.key===layoutMenu))layoutMenu=groups[0].key;return `<section class="ka-layout-studio" data-layout-studio><nav class="ka-layout-picker" aria-label="Düzenlenecek ana menü">${groups.map(g=>{const s=menuGroupSetting(g),on=g.key===layoutMenu,count=menuTargetRecords(g.key).length;return `<button type="button" class="ka-layout-picker__item ${on?'is-active':''}" data-layout-menu-select="${esc(g.key)}" aria-pressed="${on?'true':'false'}"><span>${esc(s.icon||g.icon||'')}</span><strong>${esc(s.label||g.label)}</strong><small data-layout-picker-count>${count}</small></button>`}).join('')}</nav><div class="ka-layout-panels">${groups.map(menuEditorGroup).join('')}</div></section>`}
