function dashboardEditorRow(c){return `<article class="ka-card" data-dashboard-card-row="${esc(c.key)}"><div class="ka-card__body ka-row"><div class="ka-grow"><strong>${esc(c.label)}</strong><div class="ka-muted">${esc(c.key)}</div></div><label class="ka-check"><input type="checkbox" data-card-visible ${c.visible!==false?'checked':''}> Göster</label><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-move-up>↑</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-move-down>↓</button></div></article>`}
function appLayout(){const cfg=window.AppConfig?.get?.();if(!cfg)return'<div class="ka-empty">Uygulama konfigürasyonu hazırlanıyor.</div>';const opts=cfg.modules.map(m=>`<option value="${esc(m.key)}" ${m.key===cfg.defaultModule?'selected':''}>${esc(m.label)}</option>`).join(''),sections=[['menus','▦','Menüler'],['modules','◫','Modüller'],['dashboard','⌂','Ana Sayfa']];return `<section class="ka-layout-page ka-stack"><article class="ka-card ka-layout-intro"><div class="ka-card__body"><div class="ka-layout-intro__copy"><span class="ka-badge">Merkezi Uygulama Düzeni</span><h3>Menü ve ekran düzeni</h3><p class="ka-muted">Aynı anda yalnız seçtiğiniz bölüm görünür. Sayfa konumu değişmeden menüleri, alt menüleri ve ana sayfayı düzenleyebilirsiniz.</p></div><label class="ka-field ka-layout-default"><span class="ka-field__label">Varsayılan açılış</span><select id="appDefaultModule">${opts}</select></label></div></article><nav class="ka-layout-section-tabs" aria-label="Uygulama düzeni bölümleri">${sections.map(x=>`<button type="button" class="ka-layout-section-tab ${layoutSection===x[0]?'is-active':''}" data-layout-section-select="${x[0]}" aria-pressed="${layoutSection===x[0]?'true':'false'}"><span>${x[1]}</span><strong>${x[2]}</strong></button>`).join('')}</nav><div class="ka-layout-status" data-layout-status><span>✓</span><span>Bir değişiklik yaptığınızda burada belirtilir.</span></div><section class="ka-layout-section" data-layout-section-panel="menus" ${layoutSection==='menus'?'':'hidden'}><div class="ka-layout-section-head"><div><h3>Ana menüler</h3><p class="ka-muted">Kartı seçin; yalnız o menünün ayarları ve içindeki öğeler gösterilir.</p></div></div><div id="appClassicMenuEditor">${menuLayoutEditor()}</div></section><section class="ka-layout-section" data-layout-section-panel="modules" ${layoutSection==='modules'?'':'hidden'}><div class="ka-layout-section-head"><div><h3>Modül erişimi</h3><p class="ka-muted">Teknik modüllerin adını, ikonunu, görünürlüğünü ve sırasını yönetin.</p></div></div><div id="appModuleEditor" class="ka-stack ka-layout-module-list">${cfg.modules.map(moduleEditorRow).join('')}</div></section><section class="ka-layout-section" data-layout-section-panel="dashboard" ${layoutSection==='dashboard'?'':'hidden'}><div class="ka-layout-section-head"><div><h3>Ana sayfa kartları</h3><p class="ka-muted">Dashboard kartlarının görünürlüğünü ve sırasını ayarlayın.</p></div></div><div id="dashboardCardEditor" class="ka-stack ka-layout-dashboard-list">${cfg.dashboardCards.map(dashboardEditorRow).join('')}</div></section><div class="ka-layout-savebar"><button class="ka-btn ka-btn--secondary" type="button" data-app-reset data-ka-permission="settings.app.edit" data-ka-write="settings.app.edit">Varsayılana Dön</button><button class="ka-btn" type="button" data-app-save data-ka-permission="settings.app.edit" data-ka-write="settings.app.edit">Değişiklikleri Kaydet</button></div></section>`}
function moveRow(button,dir){const row=button.closest('[data-app-module-row],[data-dashboard-card-row]'),box=row?.parentElement;if(!row||!box)return;const target=dir<0?row.previousElementSibling:row.nextElementSibling;if(target)box.insertBefore(dir<0?row:target,dir<0?target:row);markLayoutDirty(document.getElementById('settingsContent'))}
function readMenuLayoutFromDom(){const groups={};[...document.querySelectorAll('[data-menu-group-row]')].forEach((row,gi)=>{const key=row.dataset.menuGroupRow,order=Number(row.querySelector('[data-menu-group-order]')?.value);groups[key]={label:row.querySelector('[data-menu-group-label]')?.value.trim()||key,icon:row.querySelector('[data-menu-group-icon]')?.value.trim()||'',color:menuColorValue(row.querySelector('[data-menu-group-color]')?.value,''),visible:!!row.querySelector('[data-menu-group-visible]')?.checked,order:Number.isFinite(order)?order:(gi+1)*10,items:{}}});[...document.querySelectorAll('[data-menu-item-row]')].forEach((item,ii)=>{const source=item.dataset.menuItemSource||item.closest('[data-menu-group-row]')?.dataset.menuGroupRow||'';if(!source||!groups[source])return;const order=Number(item.querySelector('[data-menu-item-order]')?.value);groups[source].items[item.dataset.menuItemRow]={label:item.querySelector('[data-menu-item-label]')?.value.trim()||'',icon:item.querySelector('[data-menu-item-icon]')?.value.trim()||'',color:menuColorValue(item.querySelector('[data-menu-item-color]')?.value,''),visible:!!item.querySelector('[data-menu-item-visible]')?.checked,order:Number.isFinite(order)?order:(ii+1)*10,targetGroup:item.querySelector('[data-menu-item-target]')?.value||source}});return{groups}}
function readAppConfigFromDom(){const current=window.AppConfig.get(),modules=[...document.querySelectorAll('[data-app-module-row]')].map((row,i)=>({key:row.dataset.appModuleRow,label:row.querySelector('[data-app-label]')?.value.trim()||row.dataset.appModuleRow,icon:row.querySelector('[data-app-icon]')?.value.trim()||'',visible:!!row.querySelector('[data-app-visible]')?.checked,order:(i+1)*10})),dashboardCards=[...document.querySelectorAll('[data-dashboard-card-row]')].map((row,i)=>{const old=current.dashboardCards.find(x=>x.key===row.dataset.dashboardCardRow)||{};return{...old,key:row.dataset.dashboardCardRow,visible:!!row.querySelector('[data-card-visible]')?.checked,order:(i+1)*10}});return{defaultModule:document.getElementById('appDefaultModule')?.value||'dashboard',modules,dashboardCards,menuLayout:readMenuLayoutFromDom()}}
async function saveAppLayout(){try{window.PermissionService?.require?.('settings.app.edit','edit');await window.AppConfig.save(readAppConfigFromDom());toast?.('Uygulama düzeni cihazda kaydedildi.');render()}catch(e){toast?.('Uygulama düzeni kaydedilemedi: '+(e?.message||e))}}async function resetAppLayout(){if(!confirm('Menü ve dashboard düzeni varsayılana dönsün mü?'))return;try{window.PermissionService?.require?.('settings.app.edit','edit');await window.AppConfig.reset();toast?.('Varsayılan uygulama düzeni geri yüklendi.');render()}catch(e){toast?.('Düzen sıfırlanamadı: '+(e?.message||e))}}function selectLayoutSection(out,key){const root=out.querySelector('.ka-layout-page');if(!root)return;layoutSection=key;root.querySelectorAll('[data-layout-section-select]').forEach(b=>{const on=b.dataset.layoutSectionSelect===key;b.classList.toggle('is-active',on);b.setAttribute('aria-pressed',on?'true':'false')});root.querySelectorAll('[data-layout-section-panel]').forEach(panel=>{panel.hidden=panel.dataset.layoutSectionPanel!==key})}
