function markLayoutDirty(out){const status=out?.querySelector?.('[data-layout-status]');if(!status)return;status.classList.add('is-dirty');status.innerHTML='<span>●</span><span>Kaydedilmemiş değişiklikler var.</span>'}
function refreshLayoutCounts(out){out.querySelectorAll('[data-layout-panel]').forEach(panel=>{const count=panel.querySelectorAll('[data-menu-item-row]').length;panel.querySelectorAll('[data-layout-panel-count],[data-layout-list-count]').forEach(x=>x.textContent=String(count));const picker=out.querySelector(`[data-layout-menu-select="${panel.dataset.layoutPanel}"] [data-layout-picker-count]`);if(picker)picker.textContent=String(count);const list=panel.querySelector('[data-layout-item-list]');if(list&&count===0&&!list.querySelector('.ka-layout-empty'))list.innerHTML='<div class="ka-empty ka-layout-empty">Bu menüde alt öğe yok.</div>';if(list&&count>0)list.querySelector('.ka-layout-empty')?.remove()})}
function moveMenuItemToTarget(out,select){const row=select.closest('[data-menu-item-row]');if(!row)return;const panel=[...out.querySelectorAll('[data-layout-panel]')].find(x=>x.dataset.layoutPanel===select.value),list=panel?.querySelector('[data-layout-item-list]');if(!list)return;list.querySelector('.ka-layout-empty')?.remove();list.appendChild(row);refreshLayoutCounts(out);markLayoutDirty(out)}
function bindAppEditor(out){out.querySelectorAll('[data-move-up]').forEach(b=>b.onclick=()=>moveRow(b,-1));out.querySelectorAll('[data-move-down]').forEach(b=>b.onclick=()=>moveRow(b,1));out.querySelectorAll('[data-layout-section-select]').forEach(b=>b.addEventListener('click',()=>selectLayoutSection(out,b.dataset.layoutSectionSelect)));out.querySelectorAll('[data-layout-menu-select]').forEach(b=>b.addEventListener('click',()=>selectLayoutMenu(out,b.dataset.layoutMenuSelect)));out.querySelectorAll('[data-menu-item-target]').forEach(s=>s.addEventListener('change',()=>moveMenuItemToTarget(out,s)));out.querySelectorAll('.ka-layout-page input,.ka-layout-page select').forEach(el=>{if(el.matches('[data-menu-item-target]'))return;el.addEventListener('input',()=>markLayoutDirty(out));el.addEventListener('change',()=>markLayoutDirty(out))});out.querySelector('[data-app-save]')?.addEventListener('click',saveAppLayout);out.querySelector('[data-app-reset]')?.addEventListener('click',resetAppLayout);refreshLayoutCounts(out)}
function activeAllowed(tab){if(settingsTeacherUser()&&['users','statistics','roles'].includes(tab))return false;if(tab==='users'||tab==='statistics')return canUsers('preview');if(tab==='roles')return canRoles('preview');if(['storage','app','reminders'].includes(tab))return admin();if(tab==='school')return schoolVisible();return true}
function render(){if(!mounted)return;if(!activeAllowed(active))active='home';const out=document.getElementById('settingsContent');if(!out)return;out.innerHTML=active==='home'?settingsHome():active==='appearance'?appearance():active==='sync'?sync():active==='lesson-hours'?lessonHours():active==='lesson-list'?referenceList('lesson'):active==='branch-list'?referenceList('branch'):active==='school'?school():active==='users'?users():active==='statistics'?statistics():active==='roles'?roles():active==='storage'?storage():active==='reminders'?reminders():active==='app'?appLayout():account();out.querySelectorAll('[data-settings-open]').forEach(b=>b.onclick=()=>openPage(b.dataset.settingsOpen,b.querySelector('strong')?.textContent.trim()||b.textContent.trim()));if(active==='home')bindSettingsAccordion(out);out.querySelectorAll('[data-role-permissions]').forEach(b=>b.onclick=()=>openRoleEditor(b.dataset.rolePermissions));out.querySelector('[data-role-new]')?.addEventListener('click',()=>openRoleEditor('__new__'));if(active==='appearance')out.querySelectorAll('[data-theme-choice]').forEach(b=>b.addEventListener('click',async()=>{await window.ShellUI?.applyTheme?.(b.dataset.themeChoice);render()}));if(active==='lesson-hours')bindLessonHours(out);if(active==='lesson-list')bindReferenceList(out,'lesson');if(active==='branch-list')bindReferenceList(out,'branch');if(active==='school')bindSchool(out);if(active==='users')bindUsers(out);if(active==='statistics')bindStatistics(out);if(active==='app')bindAppEditor(out);if(active==='reminders')out.querySelector('[data-reminder-settings-save]')?.addEventListener('click',saveReminderSettings);window.PermissionService?.apply?.(document.getElementById('v2ModuleRoot')||document)}
function backSettings(){if(active!=='home'){openPage('home','Ayarlar');return true}if(window.ShellUI?.back)return window.ShellUI.back();window.ShellUI?.home?.();return true}
function bind(){document.querySelector('[data-settings-back]')?.addEventListener('click',backSettings)}function subscribe(){unsubs.forEach(f=>{try{f()}catch(_){}});unsubs=[];['session.user','session.role','ui.syncing','ui.pendingWrites','ui.lastSyncAt','ui.theme','meta.hydrated','data.okulBilgileri','data.dersSaatleri','data.dersListesi','data.bransListesi','data.ogretmenler','data.kullanicilar','data.kullaniciIstatistikleri','data.roller','data.depolamaAyarlari','data.hatirlatmaAyarlari','data.appConfig'].forEach(p=>{const u=AppStore?.subscribe?.(p,()=>requestAnimationFrame(render));if(u)unsubs.push(u)})}
async function mount(root=document.getElementById('v2ModuleRoot')){if(!root)return false;mounted=true;root.innerHTML=shell();bind();subscribe();await prepareLocal();render();return true}function openPage(page,title=''){if(!activeAllowed(page)){window.toast?.('Bu ayar sayfası için yetkiniz yok.');return false}active=page;const h=document.querySelector('[data-settings-title]'),desc=document.querySelector('[data-settings-description]');if(h)h.textContent=page==='home'?'Ayarlar':(title||h.textContent);if(desc)desc.textContent=settingsDescription(page);render();if(page==='statistics')void prepareStatisticsData(false);return true}
