window.SettingsModule={mount,unmount,render,prepareLocal,openPage,back:backSettings,openRoleEditor,openUserEditor,saveReminderSettings};window.addEventListener('koruk:module-ready',e=>{if(e.detail?.name==='settings')mount()});
